# * Drum level trim per drum voice (MU1000 / MU128 drum data), measured on the S-MU2000.
#
# syxg50.dll plays drum samples with a different frequency balance than the MU: about 1 dB less
# above 6 kHz and 0.3 dB more below 800 Hz (median over all keys), and the loss shifts with the
# pitch of the key, so it is not a fixed filter (issue #5: Ride 2 -0.9 dB, crash / ride cymbals,
# shakers and triangles -0.6..-1.6 dB, kicks and toms up to +1.8 dB). A model from the sample
# spectrum only explained part of it, so the level byte of each drum voice is corrected by its
# measured deviation instead: drum sweep (31 XG + 8 SFX kits, every key, velocity 100, energy of
# the first 1.15 s), S-YXG minus S-MU2000 after the global DRUM_LEVEL_GAIN_DB.
# The 198 drum voices used by more than one kit came out the same within 0.14 dB (90 %).
#
# key: CRC32 of the 42 source bytes of the drum voice, value: trim in 0.1 dB (only |trim| >= 0.15 dB).
#
# syxg50.dll does not play the drum level byte on a smooth curve: it is quantized in steps of
# 0.5-1 dB (DRUM_LEVEL_STEPS, measured on the emulator: levels 115-119 all play at -1.7 dB,
# 120-124 at -0.8 dB, 125-127 at 0 dB). So the trimmed level is the byte whose step comes
# closest to the measured level plus the trim. Boosts stop at the top step (125-127, 140 voices).

# (lowest level byte of the step, dB relative to level 127), from the top
DRUM_LEVEL_STEPS = ((125, 0.0), (120, -0.8), (115, -1.7), (110, -2.8), (106, -3.3), (101, -3.9), (97, -4.6), (92, -5.3),
    (88, -6.0), (84, -6.8), (82, -7.8), (78, -8.8), (74, -9.4), (70, -10.0), (68, -10.6), (65, -11.3), (63, -12.0),
    (60, -12.9), (58, -13.8), (55, -14.8), (53, -15.4), (50, -16.0), (49, -16.6), (46, -17.3), (45, -18.1), (43, -18.9),
    (41, -19.8), (39, -20.9), (38, -21.4), (36, -22.0), (35, -22.6), (32, -23.3), (31, -24.1), (30, -24.9), (29, -25.8),
    (27, -26.9), (26, -27.4), (25, -28.0), (24, -29.4), (22, -30.1), (21, -30.9), (20, -32.9), (19, -33.4), (17, -34.0),
    (16, -35.4), (15, -36.9), (13, -38.9), (12, -40.1), (11, -41.4), (10, -44.9), (8, -46.1), (7, -49.0), (6, -52.1),
    (5, -57.0), (3, -61.0), (2, -69.0), (1, -80.3))

def Level_dB(level : int) -> float :
    return next(db for low, db in DRUM_LEVEL_STEPS if level >= low)

def Trimmed_Level(level : int, raw : bytes | bytearray) -> int :
    import zlib
    trim = TRIM_DB10.get(zlib.crc32(raw), 0) / 10
    if not trim or not level : 
        return level
    target = Level_dB(level) + trim
    # nearest step; within it the byte closest to the old one
    return min(range(1, 128), key=lambda b : (round(abs(Level_dB(b) - target), 2), abs(b - level)))

